-- SwiftDrop Buy & Deliver destination and payment state.
ALTER TABLE buy_orders ADD COLUMN IF NOT EXISTS receiver_name TEXT, ADD COLUMN IF NOT EXISTS receiver_phone TEXT, ADD COLUMN IF NOT EXISTS receiver_pin_hash TEXT, ADD COLUMN IF NOT EXISTS destination_address TEXT, ADD COLUMN IF NOT EXISTS destination_lat NUMERIC(9,6), ADD COLUMN IF NOT EXISTS destination_lng NUMERIC(9,6), ADD COLUMN IF NOT EXISTS merchant_lat NUMERIC(9,6), ADD COLUMN IF NOT EXISTS merchant_lng NUMERIC(9,6), ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (payment_status IN ('PENDING','AUTHORIZED','HELD','REFUNDED','FAILED')), ADD COLUMN IF NOT EXISTS payment_reference TEXT;
CREATE INDEX IF NOT EXISTS idx_buy_orders_payment_status ON buy_orders(payment_status, created_at DESC);
CREATE TABLE IF NOT EXISTS buy_order_payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), buy_order_id UUID NOT NULL UNIQUE REFERENCES buy_orders(id) ON DELETE CASCADE, provider TEXT NOT NULL, provider_reference TEXT UNIQUE, amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'NGN', status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','AUTHORIZED','HELD','RELEASED','REFUNDED','FAILED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_buy_order_payments_status ON buy_order_payments(status);